
CALL AlterTableAddColumn ('ASSET','NAME','VARCHAR(200)  DEFAULT NULL AFTER `MONITOR`');
CALL AlterTableAddColumn ('ASSET','OPERATING_SYSTEM','VARCHAR(200)  DEFAULT NULL AFTER `NAME`');
CALL AlterTableAddColumn ('ASSET','OS_KEY','VARCHAR(100)  DEFAULT NULL AFTER `OPERATING_SYSTEM`');
CALL AlterTableAddColumn ('ASSET','ANTI_VIRUS','VARCHAR(200)  DEFAULT NULL AFTER `OS_KEY`');
CALL AlterTableAddColumn ('ASSET','PURCHASE_DATE','DATE  DEFAULT NULL AFTER `ANTI_VIRUS`');
CALL AlterTableAddColumn ('ASSET','COST','DECIMAL  DEFAULT NULL AFTER `PURCHASE_DATE`');
CALL AlterTableAddColumn ('ASSET','DEPRECIATION_DATE','DATE  DEFAULT NULL AFTER `COST`');
CALL AlterTableAddColumn ('ASSET','DEPRECIATION_AMOUNT','DECIMAL  DEFAULT NULL AFTER `DEPRECIATION_DATE`');
CALL AlterTableAddColumn ('ASSET','VENDOR_DETAILS','VARCHAR(200)  DEFAULT NULL AFTER `DEPRECIATION_AMOUNT`');


CALL AlterTableAddColumn ('ASSET_ASSIGN','ASSIGNED_ON','DATE  DEFAULT NULL AFTER `USER_ROLE_ID`');
CALL AlterTableAddColumn ('ASSET_ASSIGN','RETURNED_ON','DATE  DEFAULT NULL AFTER `ASSIGNED_ON`');


